divide_and_double :: proc(n: f32, d: f32) -> (f32, bool) #optional_ok {
	if d == 0 {
		return 0, false
	}

	return (n/d)*2, true
}

main :: proc() {
	num := divide_and_double(25, 5)
	fmt.println(num)
}

